with valid as (select id, store_id, product_id, quantity, coalesce(quantity, 0) as quantity_filled from inventory where last_restock > date '2023-09-11'), cleaned as (select id, store_id, product_id, quantity, quantity_filled, cast(quantity_filled as int) as quantity_filled_int from valid where quantity_filled between 20 and 60), enriched as (select s.id, s.store_id, s.product_id, s.quantity, s.quantity_filled, s.quantity_filled_int, p.store_name, p.sqft from cleaned s join stores p on s.store_id = p.id), with_windows as (select id, store_id, quantity_filled, sqft, row_number() over (partition by store_id order by sqft, id) as row_seq, min(quantity_filled_int) over (partition by store_id) as store_id_min_quantity_filled_int, avg(quantity_filled_int) over (partition by store_id order by quantity_filled_int, id rows between 5 preceding and current row) as quantity_filled_int_avg_5 from enriched where store_id in (1, 2, 5, 6)), summary as (select case when store_id_min_quantity_filled_int >= 71 then 'PREMIUM' else 'STANDARD' end as store_id_min_quantity_filled_int_tier, store_id, percentile_approx(quantity_filled, array(0.25, 0.5, 0.75)) as quantity_filled_quartiles, round(avg(store_id_min_quantity_filled_int), 2) as avg_store_id_min_quantity_filled_int, round(avg(quantity_filled), 2) as avg_quantity_filled, max(quantity_filled) as max_quantity_filled, approx_percentile(quantity_filled_int_avg_5, array(0.25, 0.5, 0.75)) as quantity_filled_int_avg_5_quartiles from with_windows group by case when store_id_min_quantity_filled_int >= 71 then 'PREMIUM' else 'STANDARD' end, store_id) select s.store_id_min_quantity_filled_int_tier, s.store_id, s.quantity_filled_quartiles, s.max_quantity_filled, (select sum(s2.revenue) from store_sales s2 where s2.store_id = s.store_id) as sum_store_sale_revenue from summary s order by max_quantity_filled;
